CREATE OR REPLACE FUNCTION public.profiles_guard_admin_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_service BOOLEAN;
  v_admin BOOLEAN;
BEGIN
  IF NEW.role_id IS DISTINCT FROM OLD.role_id
     OR NEW.account_status IS DISTINCT FROM OLD.account_status
     OR NEW.approved_by IS DISTINCT FROM OLD.approved_by
     OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
     OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN

    SELECT (auth.role() = 'service_role'
            OR current_user IN ('postgres', 'supabase_admin'))
    INTO v_service;
    SELECT public.is_app_role(ARRAY['hrd', 'super_admin']) INTO v_admin;

    IF NOT (v_service OR v_admin) THEN
      RAISE EXCEPTION 'DITOLAK: kolom administratif profil (role/status) hanya boleh diubah admin';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.vendor_guard_restricted_columns()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_service_context BOOLEAN;
BEGIN
  SELECT (
    auth.role() = 'service_role'
    OR current_user IN ('postgres', 'supabase_admin')
  )
  INTO v_service_context;

  IF (NEW.qualification_status IS DISTINCT FROM OLD.qualification_status
      AND (NEW.qualification_status IN ('APPROVED','RESERVE','REJECTED','FROZEN')
           OR OLD.qualification_status IN ('APPROVED','RESERVE','REJECTED','FROZEN')))
     OR NEW.operational_status IS DISTINCT FROM OLD.operational_status
     OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id
     OR NEW.activated_at IS DISTINCT FROM OLD.activated_at
     OR NEW.activated_by IS DISTINCT FROM OLD.activated_by THEN

    IF NOT v_service_context THEN
      RAISE EXCEPTION 'DITOLAK: keputusan kelayakan & aktivasi vendor hanya melalui mekanisme persetujuan khusus (Fase 5) — bukan perubahan status langsung';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.vendor_record_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_actor UUID;
BEGIN
  SELECT up.id INTO v_actor FROM user_profiles up WHERE up.auth_user_id = auth.uid();
  v_actor := COALESCE(v_actor, NEW.updated_by);

  IF OLD.process_stage IS DISTINCT FROM NEW.process_stage THEN
    INSERT INTO vendor_status_history (candidate_id, field_name, old_value, new_value, changed_by)
    VALUES (NEW.id, 'process_stage', OLD.process_stage, NEW.process_stage, v_actor);
  END IF;
  IF OLD.qualification_status IS DISTINCT FROM NEW.qualification_status THEN
    INSERT INTO vendor_status_history (candidate_id, field_name, old_value, new_value, changed_by)
    VALUES (NEW.id, 'qualification_status', OLD.qualification_status, NEW.qualification_status, v_actor);
  END IF;
  IF OLD.operational_status IS DISTINCT FROM NEW.operational_status THEN
    INSERT INTO vendor_status_history (candidate_id, field_name, old_value, new_value, changed_by)
    VALUES (NEW.id, 'operational_status', OLD.operational_status, NEW.operational_status, v_actor);
  END IF;
  RETURN NEW;
END;
$function$
